create policy "Families read borrowed book details" on public.schoolpro_library_books for select to authenticated using (coalesce(private.is_active_account(),false) and private.schoolpro_operationally_active(school_id) and exists(select 1 from public.schoolpro_library_loans l where l.book_id=schoolpro_library_books.id and l.school_id=schoolpro_library_books.school_id and l.student_id is not null));